using Microsoft.EntityFrameworkCore.ValueGeneration;
using Microsoft.EntityFrameworkCore.ChangeTracking;

// Breaking change 2 fix: Generates ids in the legacy "Discriminator|Key" format
// to remain compatible with existing documents whose id = "Blog|1", etc.
class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry)
        => $"{entry.Metadata.ShortName()}|{Guid.NewGuid()}";
}

class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }

        // Breaking change 4: EF Core 9 uses sync-over-async detection for Cosmos.
        // SaveChanges() now throws by default; use SaveChangesAsync() instead.
        // context.SaveChanges(); // BROKEN in EF Core 9 for Cosmos provider
    }

    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

